pub assume_specification<T, E>[ Result::<Result<T, E>, E>::flatten ](
    result: Result<Result<T, E>, E>,
) -> (flattened: Result<T, E>)
    ensures
        flattened == match result {
            Result::Ok(inner) => inner,
            Result::Err(error) => Result::Err(error),
        },
    no_unwind
;
